const state={queues:[],streams:[],nodes:[],controller:null,filter:""};
const $=id=>document.getElementById(id);
const fmt=n=>new Intl.NumberFormat().format(Number(n||0));
const bytes=n=>{n=Number(n||0);if(!n)return "0 B";const u=["B","KiB","MiB","GiB","TiB"],i=Math.min(Math.floor(Math.log(n)/Math.log(1024)),u.length-1);return `${(n/1024**i).toFixed(i?1:0)} ${u[i]}`};
const esc=v=>String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
async function get(url){const r=await fetch(url,{headers:{Accept:"application/json"}});if(!r.ok){const body=await r.json().catch(()=>({}));throw new Error(body.error?.message||`${r.status} ${r.statusText}`)}return r.json()}
async function loadDashboard(){
  $("refresh").disabled=true;$("alert").hidden=true;
  const requests=["/api/v1/info","/api/v1/cluster","/api/v1/nodes","/api/v1/queues?limit=200","/api/v1/streams?limit=200","/api/v1/controller"].map(get);
  const [info,cluster,nodes,queues,streams,controller]=await Promise.allSettled(requests);
  const errors=[info,cluster,nodes,queues,streams,controller].filter(x=>x.status==="rejected").map(x=>x.reason.message);
  if(info.status==="fulfilled"){$("service-meta").textContent=`${info.value.name} ${info.value.version} · ${info.value.nats_url} · uptime ${formatDuration(info.value.uptime_seconds)}`;setService(true)}else setService(false);
  if(nodes.status==="fulfilled"){state.nodes=nodes.value.nodes||[];renderNodes(nodes.value)}
  if(queues.status==="fulfilled")state.queues=queues.value.items||[];if(streams.status==="fulfilled")state.streams=streams.value.items||[];
  state.controller=controller.status==="fulfilled"?controller.value:null;if(cluster.status==="fulfilled")renderMetrics(cluster.value);renderQueues();renderController();
  if(errors.length){$("alert").textContent=`Partial data: ${[...new Set(errors)].join(" · ")}`;$("alert").hidden=false}
  $("last-updated").textContent=`Updated ${new Date().toLocaleTimeString()}`;$("refresh").disabled=false;
}
function setService(ok){$("service-dot").className=`dot ${ok?"good":"bad"}`;$("service-state").textContent=ok?"Management ready":"Management unavailable"}
function renderMetrics(cluster){const a=cluster.account||{},snapshot=state.nodes;$("metric-health").textContent=snapshot.length&&snapshot.every(n=>n.status==="available")?"Healthy":"Check";$("metric-nodes").textContent=`${fmt(snapshot.length)} nodes`;$("metric-queues").textContent=fmt(state.queues.length);$("metric-streams").textContent=`${fmt(a.streams)} streams`;$("metric-messages").textContent=fmt(state.streams.reduce((n,s)=>n+Number(s.messages||0),0));$("metric-storage").textContent=`${bytes(a.storage_used)} stored`}
function renderController(){const c=state.controller;$("metric-dlq").textContent=c?fmt(c.dlqMoved):"—";$("metric-controller").textContent=c?`${c.leader?"leader":"follower"} · ${fmt(c.dlqFailed)} failed`:"controller unavailable"}
function streamFor(q){return state.streams.find(s=>s.name===`RJSQ_${q.queue}`)}
function renderQueues(){const rows=state.queues.filter(q=>q.queue.toLowerCase().includes(state.filter)).map(q=>{const s=streamFor(q),ready=!!s;return `<tr data-queue="${esc(q.queue)}" tabindex="0"><td><strong>${esc(q.queue)}</strong></td><td><span class="badge ${ready?"good":"bad"}">${ready?"Ready":"Missing"}</span></td><td class="number">${s?fmt(s.messages):"—"}</td><td class="number">${s?fmt(s.consumers):"—"}</td><td>${esc(s?.storage||"—")}</td><td>${s?fmt(s.replicas):"—"}</td><td><code>${esc(q.revision?.slice(0,10)||"—")}</code></td></tr>`}).join("");$("queue-rows").innerHTML=rows||'<tr><td colspan="7" class="empty">No queues match this filter.</td></tr>';$("metric-queues").textContent=fmt(state.queues.length);$("metric-streams").textContent=`${fmt(state.streams.length)} streams`;$("metric-messages").textContent=fmt(state.streams.reduce((n,s)=>n+Number(s.messages||0),0));document.querySelectorAll("tr[data-queue]").forEach(row=>{const open=()=>openQueue(row.dataset.queue);row.addEventListener("click",open);row.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();open()}})})}
function renderNodes(snapshot){$("node-summary").textContent=`${fmt(snapshot.available)} available · ${fmt(snapshot.degraded)} degraded · ${fmt(snapshot.unavailable)} unavailable`;$("node-grid").innerHTML=(snapshot.nodes||[]).map(n=>`<article class="node"><div class="node-head"><h3>${esc(n.name||n.endpoint)}</h3><span class="badge ${n.status==="available"?"good":n.status==="degraded"?"warn":"bad"}">${esc(n.status)}</span></div><dl><div><dt>Version</dt><dd>${esc(n.version||"—")}</dd></div><div><dt>Uptime</dt><dd>${esc(n.uptime||"—")}</dd></div><div><dt>Memory</dt><dd>${bytes(n.memory_bytes)}</dd></div><div><dt>CPU</dt><dd>${Number(n.cpu_percent||0).toFixed(1)}%</dd></div><div><dt>Connections</dt><dd>${fmt(n.connections)}</dd></div><div><dt>JS messages</dt><dd>${fmt(n.jetstream?.messages)}</dd></div></dl></article>`).join("")||'<p class="empty">No monitoring nodes are available.</p>'}
async function openQueue(name){const declaration=state.queues.find(q=>q.queue===name),stream=streamFor(declaration),dialog=$("queue-dialog");$("dialog-title").textContent=name;$("dialog-body").innerHTML='<div class="dialog-section muted">Loading consumer state…</div>';dialog.showModal();try{const page=stream?await get(`/api/v1/streams/${encodeURIComponent(stream.name)}/consumers?limit=200`):{items:[]};const consumers=page.items||[],plan=declaration.plan||{};$("dialog-body").innerHTML=`<section class="dialog-section"><h3>Runtime</h3><dl class="detail-grid"><div><dt>Messages</dt><dd>${stream?fmt(stream.messages):"—"}</dd></div><div><dt>Bytes</dt><dd>${stream?bytes(stream.bytes):"—"}</dd></div><div><dt>Retention</dt><dd>${esc(stream?.retention||"—")}</dd></div><div><dt>Created</dt><dd>${stream?new Date(stream.created).toLocaleString():"—"}</dd></div></dl></section><section class="dialog-section"><h3>Subjects</h3><div class="subject-list">${(plan.stream?.subjects||[]).map(s=>`<code>${esc(s)}</code>`).join("")||"—"}</div></section><section class="dialog-section"><h3>Consumers</h3>${consumers.map(c=>`<dl class="detail-grid"><div><dt>Name</dt><dd>${esc(c.name)}</dd></div><div><dt>Pending</dt><dd>${fmt(c.pending)}</dd></div><div><dt>Ack pending</dt><dd>${fmt(c.ack_pending)}</dd></div><div><dt>Redelivered</dt><dd>${fmt(c.redelivered)}</dd></div></dl>`).join("")||'<p class="muted">No consumer found.</p>'}</section>`}catch(e){$("dialog-body").innerHTML=`<div class="dialog-section alert">${esc(e.message)}</div>`}}
function formatDuration(seconds){seconds=Number(seconds||0);const d=Math.floor(seconds/86400),h=Math.floor(seconds%86400/3600),m=Math.floor(seconds%3600/60);return d?`${d}d ${h}h`:h?`${h}h ${m}m`:`${m}m`}
$("refresh").addEventListener("click",loadDashboard);$("queue-filter").addEventListener("input",e=>{state.filter=e.target.value.trim().toLowerCase();renderQueues()});$("dialog-close").addEventListener("click",()=>$("queue-dialog").close());$("queue-dialog").addEventListener("click",e=>{if(e.target===$("queue-dialog"))$("queue-dialog").close()});loadDashboard();setInterval(loadDashboard,10000);
